const fail = (ms, message) =>
  new Promise((resolve, reject) => setTimeout(() => reject(new Error(message)), ms));

Promise.any([fail(50, "north"), fail(10, "south"), fail(30, "east")]).catch((error) => {
  console.log(error.name);
  console.log(error.errors.map((reason) => reason.message).join(","));
});

Promise.any([]).catch((error) => console.log("empty", error.errors.length));

Promise.race([]).then(() => console.log("race done"));
